package com.coyotevision.app

/** Static explanations live beside their titles; live instructions and measurements stay visible. */
internal object UiHelp {
    private val mapping = "额外幅度指超出本轮校准抖动容许量的部分，以校准肩宽为单位，5–200%。例如肩宽画面长度为 200，设置 20%，就是超出抖动容许量 40 个画面坐标单位时达到该动作最高强度。不是厘米。\n\n比例 q＝clamp（超出抖动阈值的幅度 ÷ 设置幅度，0，1）；该动作目标＝常态＋（该动作最高强度－常态）×q。常态 10、最高 30，超出量为所设幅度的一半时目标 20，达到全部幅度时目标 30，继续增大不再超过 30。实际请求按上升速度靠近目标，整数取整，下降立即生效喵。\n\n手部取手腕固定位置偏移、双手分离增量与近一秒路程的较大值；脚步取腿脚偏移、张腿量与近一秒路程的较大值。因此往返动作也会计入，站回后近期路程可能延续约一秒。控制台显示当前额外幅度与设定满幅值。"
    private val logs = "教官只记必要变化喵：手、脚、输出强度、异常和开始/暂停/停止。移除逐帧坐标、映射计算与重复设备回报；输出与姿态不变时不重复记录。普通变化至少间隔 2 秒，强度变化达到 5 或手脚评分变化达到 20 个百分点才记录；更小但持续的变化至多每 10 秒补记一次。\n\n同一阶段内，手或脚评分达到 50%、对应增量启用，且最近 2 秒内已提交或虚拟强度中的动作增量上升至少 8，记一次突增提醒并闪烁橙色边框 1.6 秒。保持高位不连续提醒；训练基础缓升、切换阶段或只有目标变化不算动作突增。行礼阶段边框优先，提醒不会增加电流。数值为协议强度单位，不是人体电流测量。\n\n普通记录按分钟共用时间标记；突增、异常、开始/暂停/停止保留具体时间。控制台显示最近 6 条，精简日志按时间顺序查看和复制。只存内存，最多保留最近 500 条，新一轮清空，重新校准继续则保留。画面本地分析，不保存照片或视频。"

    private val timing = "小公主，校准完成后才正式开始罚站、输出和计时喵。本轮总时长可设 1–90 分钟，默认 3 分钟。常态、三连提示、行礼判定、惩罚、两秒调整期和忍耐训练共用本轮总时长，不额外加时；时间到点优先停止。\n\n人物主体持续丢失会暂停计时及输出，重新完成平举确认、屈膝礼记录和站姿校准后继续剩余时间。手腕或腿脚短暂测量不足也暂停，恢复可靠跟踪后沿用原校准。被打断任务取消，不补发惩罚。"
    private val training = "小公主的进阶考验仍要守好站姿喵。忍耐训练使用这里的基础强度、通道和波形，目标＝训练基础强度＋各动作升幅中的最大值，且不超过全局最高；动作升幅由普通动作最高减去普通常态后按动作比例计算。基础与动作增量一起按固定每秒 30 协议强度单位缓升，下降立即生效。\n\n训练与屈膝礼任务不重叠，训练结束后再安排行礼提示；临近本轮结束不再开启训练。训练期间也要站稳喵，教官会继续看着小公主的手脚。"
    private val pairing = "小公主上课前，先让两部手机配好对喵。两部手机连接允许设备互通的同一 Wi-Fi。本机负责姿态识别并显示二维码；另一部手机使用 DGLAB 4.0 的 Socket 控制扫码入口扫描，且只保留一台已通过蓝牙连接的郊狼 2.0 或 3.0。程序自动识别型号，读取设备后才显示已配对；同时连接两代或多台郊狼时，请只保留一台。\n\n两代设备均使用官方 App 的强度与波形接口，本机范围仍为 0–200，不按硬件代际自动放大强度。二维码只对当前连接有效，重新连接需重新扫码。配对后回到本机，选择养成模式，再点击开始罚站。内置连接无需电脑或外部服务器；外部 V3 兼容连接仅供测试，不支持本版游戏设备输出。"

    private val entries = mapOf(
        "welcome" to "欢迎来到小公主的礼仪课喵～皇冠要戴稳，罚站也要站好。\n\n小公主养成从保持站姿开始：站稳、双手回到本轮记录的位置；手脚活动和整体离位会按你设置的最高强度及动作幅度调整目标。可以开启随机屈膝礼与忍耐训练。先使用虚拟输出查看识别和联动结果，再自行选择设备输出。\n\n只适用于单人画面，请固定手机并让全身入镜。退出前台或连接异常会结束本轮；网络断开时，软件无法保证停止指令到达设备。停止、取消和返回设置始终保留。",
        "camera_access" to "小公主点“开启摄像头”，教官才开始看站姿喵。首页只显示功能框，不创建摄像头控制器或姿态检测器；没有点击时不申请摄像头权限，也不因以前授过权而自动开启。\n\n点击后才按需请求权限、启动摄像头并展开预览。此时只做本地识别，仍需另点“开始罚站”并完成三步校准后才计时和输出。可以关闭摄像头；关闭时会停止本轮、释放镜头并收起预览。\n\n退到后台或离开应用会停止本轮并释放摄像头，返回后需重新点击开启；仅正在等待的权限弹窗会保留刚才的开启请求，允许后才继续。拒绝权限、关闭或退出后到达的旧启动结果和旧画面不再生效。授予系统权限本身不会启动摄像头。",
        "preview" to "先点击首页功能框开启摄像头，再开始罚站喵。小公主的罚站和屈膝礼姿势，要先让教官记住喵：点击开始罚站后，退到合适位置，双臂向两侧平举 2 秒确认；接着做屈膝礼，保持 3 秒有效画面；最后起身，将双手靠近并放到自己选择的腹前位置，手腕稳定保持 5 秒；靠近距离可在“02 罚站规矩与电流”调整。肩部短暂闪烁保留手腕进度，结束时用近期可靠的全身坐标保存基准。屈膝礼校准和游戏判定以双手位置与髋部下沉为主，肩部辅助确认位置；膝盖和脚踝闪烁、低置信度或短暂消失不打断保持，也不重开当前任务。只要肩、髋和双手清晰，就继续本次判定；不是沿用旧腿部坐标。手部或髋部遮挡时，校准阶段 3 秒内保留进度，遮挡时间不计入保持；超过 3 秒只重采屈膝礼，仍保留已确认的位置。人物主体连续丢失 5 秒才退回平举确认；位置测量持续偏离 0.6 秒也会要求重新定位。调整下蹲深度后，以最后停稳的姿势重新采集，并用结束前 1 秒的有效画面记录目标。全部完成后才输出和计时，之后请保持好这次记录的站姿哦。\n\n手位以实际静止位置为准，不估算肚脐，也不检测手指。金色点是手腕、双膝和脚踝；灰圈固定在校准时的背景坐标，蓝线显示位移及近期轨迹。手部基准框和记录位置固定，手指、脚趾不参与评分。",
        "section_01" to pairing,
        "phone_ip" to "选择本机的 Wi-Fi IPv4 地址，另一部手机需能通过同一局域网访问它。未找到地址时先连接 Wi-Fi，再刷新；更换地址前请先关闭现有连接喵。",
        "external" to "已有 V3 服务时可以保留外部连接方式，填写 ws:// 或 wss:// 地址。此入口用于兼容测试，不支持本版 DGLAB 4 游戏设备输出；日常两手机游玩请使用上方的内置连接。",
        "section_02" to "小公主先定好最高强度，再决定动作多大时达到它喵。全局最高输出强度限制所有阶段；常态是站稳时的强度。手、脚、躯干和离位分别填写绝对目标，不再填写叠加权重，0 关闭对应动作。各动作最高强度需在常态与全局最高之间。\n\n普通目标＝常态＋max（手部升幅、脚步升幅、躯干升幅、离位升幅），各项升幅为（对应最高－常态）×动作比例；多项同时活动只取最大结果，最后受全局最高限制。\n\n例：常态 10、手部最高 30、脚步最高 40，手脚均到满幅时为 40，未相加到 60。上升速度仅决定多久接近目标。时长规则与行礼、惩罚保持原设置；所有强度都是协议数值，不是安培读数。",
        "wrist_near_percent" to "用于第三步站姿确认：双腕间距不超过定位时肩宽的这个百分比，就算靠近。范围 5–150%，默认 70%；调大更宽松，调小更严格喵。它是靠近判定的距离上限。\n\n双手放下并在所选腹前位置保持 5 秒；手腕移动、明显分开或手腕持续不清晰会重新记录。肩部或手肘短暂闪烁不清零手腕进度。手位时间完成后，还会等近期可靠的身体坐标、起身及双脚靠拢再保存基准，期间不输出、不计游戏时间。\n\n本项只控制第三步的靠近确认；普通阶段手部增量仍按本轮记录的手位、阈值和映射范围计算。",
        "limit" to "所有阶段都不能超过这个全局最高输出强度，范围 0–200，默认 0。它是硬上限，不会自动让每种动作都达到这个值。各动作还可设置自己的绝对最高强度；要让某个动作在满幅时达到全局最高，就把该动作最高填写为相同数值。\n\n这里是提交给官方 App 的协议强度数值；官方 App 的通道上限、静音、连接和设备状态仍影响实际表现。App 回报与本机提交分开显示，都不是人体电流测量。",
        "normal_strength" to "站稳时的基础强度，默认 0，不超过全局最高。普通罚站的动作输出在此值与各自最高强度之间线性变化，通道和波形在“普通罚站通道与波形”中选择。\n\n行礼提示、行礼过程、惩罚和忍耐训练仍按各自设置执行。更改常态后，各已启用的动作最高需保持不低于常态，否则不会开始本轮。",
        "motion" to "仅选择普通罚站（含常态及动作输出）的通道和波形。最高强度直接使用下方手部、脚步、躯干及离位设置；不再额外叠加旧版综合身体幅度强度。",
        "motion_rise_rate" to "普通站立阶段动作增量接近目标的最大速度，范围 1–200 协议强度单位/秒，默认 4。数值越大，增加越快；常态电流仍作基础值，下降立即生效。\n\n忍耐训练固定每秒 30；行礼过程及惩罚按各自预设执行。本项不会改变它们的规则喵。",
        "hand_mapping_range" to "手部达到自身最高强度所需的额外幅度，默认 65% 校准肩宽；数值越小，越小的动作就会达到手部最高。\n\n" + mapping,
        "foot_mapping_range" to "脚步达到自身最高强度所需的额外幅度，默认 35% 校准肩宽，独立于手部。\n\n" + mapping,
        "zone_radius" to "以本轮记录的站立位置为基准，按校准肩宽的百分比确定范围半径，范围 20–200%，默认 50%。髋中心和脚踝中心均超出才触发整体离位，数值越大允许的活动范围越大。",
        "hand_peak" to "手部动作达到所设额外幅度时的绝对目标强度，0 关闭此项。例：常态 10、手部最高填 30，满幅就是 30；无需再加常态。手和脚同时活动时，采用较高目标。\n\n只识别手腕位置与手间距，不检测手指或肚脐。\n\n",
        "foot_peak" to "腿脚动作达到所设额外幅度时的绝对目标强度，0 关闭此项。例：常态 10、脚步最高填 40，半幅目标为 25，满幅为 40。双脚反向移动不会互相抵消；与其他动作取较高目标，不重复相加。",
        "torso_peak" to "肩和髋相对校准背景位置移动时的绝对最高目标强度，0 关闭。使用肩、髋中最大的固定坐标偏移及独立满幅设置；不把手脚评分重复算入躯干。\n\n本项替换旧版“身体幅度最大增量/灵敏度”，旧综合项不能直接对应新躯干测量，升级后本项默认关闭，需自行设置。",
        "zone_peak" to "髋中心与脚踝中心均离开所设站立范围时，采用这里填写的绝对目标强度，0 关闭。例：常态 10、离位填 35，离位目标就是 35。与手脚和躯干目标取最高值，并受全局最高及上升速度限制，不再额外累加此值。",
        "torso_mapping_range" to "躯干达到自身最高强度所需的额外幅度，默认 50% 校准肩宽，范围 5–200%。肩和髋相对固定基准的最大偏移超出抖动容许量后线性上升；手脚动作不算入此幅度。比例达到一半时，目标是常态与躯干最高的中间值，满幅达到躯干最高。",
        "output_preview" to "这里实时列出站稳强度、全局最高、各类动作最高、半幅目标及满幅距离，方便小公主对照喵。强度项是绝对值，动作目标不重复相加；若参数非法，会指出需要调整的范围。\n\n忍耐训练保留“训练基础＋动作违规升幅”，升幅由（普通动作最高－常态）换算并在多项动作中取最大值，再受全局最高限制；开启训练时，预览会另列训练的含动作最高强度。例如常态 10、手部最高 30、训练基础 25，则训练中手部满幅为 45，仍受全局最高限制。\n\n旧版手、脚和离位增量会一次性换成常态＋旧增量的绝对值并限制到全局最高；多项不再累加。旧综合身体项改成独立躯干项，默认关闭，原有手脚幅度设置保留。",
        "section_03" to "小公主的宫廷礼仪可不能马虎喵，罚站和屈膝礼都要认真。先播放三秒三连提示，再进入行礼判定；完成则恢复常态并给两秒调整，超时则播放一次所选惩罚波形。\n\n" + timing,
        "game" to "开启后，教官会在本轮罚站总时间内随机安排屈膝礼考核喵。关闭此项仍可进行普通站姿监测和独立启用的忍耐训练，本轮时长依然生效。程序只能识别身体姿态，不能确认是否抓住裙摆。",
        "minutes" to timing,
        "gap_min" to "随机行礼提示间隔的下界，范围 5–300 秒。与最长间隔一起决定随机等待范围，下界不能大于上界；训练与行礼不重叠，不会因此延长本轮总时长。",
        "gap_max" to "随机行礼提示间隔的上界，范围 5–300 秒，不得小于最短间隔。临近本轮结束时，不会额外增加游戏时间来等待任务。",
        "response" to "三秒三连提示播放完后，才开始这个行礼判定期限，范围 3–30 秒。需先确认站姿，再做到本轮记录的屈膝礼并连续保持所选时长；期限至少比保持时间长 0.5 秒。该期限包含在本轮总时长里，不额外计时。",
        "curtsey_range" to "默认 30%，可设校准肩宽的 10–80%，越大越宽松。以本轮记录的肩、髋和双手腕为目标，逐点检查所选半径，并确认髋部下沉接近记录值；用于行礼前站姿确认及屈膝礼匹配。腿部点不参与本次行礼保持，闪烁或丢失不重置任务或进度。\n\n游戏画面显示目标骨架和范围圈，圈绿为范围内、红为范围外。仍需髋部实际下沉并匹配手位，不能只挪动双手或用宽松范围把站立当作行礼。普通站姿动作评分不受此范围影响。",
        "curtsey_hold" to "小公主先站好，再做到本轮校准的屈膝礼并连续保持所选时长，达标当下就算成功，不必等起身。手位或髋部离开目标姿势会重新累计保持时间；仅腿部点闪烁或丢失不会清零。\n\n行礼合格后，给小公主固定 2 秒回到罚站姿势喵：恢复常态电流，暂停动作违规增量；两秒后继续普通监测。调整时间也计入本轮总时间，旧任务不会因尚未站好再判失败。",
        "cue" to "行礼前播放完整的三秒三连提示，可独立选择提示强度、通道与提示波形；此时替代普通输出，不叠加动作增量。黄色边框同步亮起三次，提示结束才进入蓝色判定，不提前累计行礼保持时间或消耗判定期限。",
        "cue_strength" to "三连提示的独立强度，不跟随常态或屈膝礼过程强度。设备模式启用随机行礼时需为 1 到本机总上限；虚拟模式可用 0 观察边框与任务流程。",
        "curtsey" to "三连提示结束后，在行礼判定期间使用这里的独立过程强度、通道和波形，替代常态电流，不叠加动作增量；强度 0 为关闭过程输出。三连提示本身按提示预设播放。\n\n完成则结束过程电流、恢复常态，绿色边框提示两秒调整期；超时先停止过程电流，再进入惩罚。下蹲动作按本轮校准目标判断喵。",
        "curtsey_strength" to "判定期间独立的目标强度，0 为关闭过程输出。它替代常态电流，不加动作增量；设备模式不得超过本机总上限。",
        "penalty_delta" to "行礼超时的惩罚按这里的规矩执行喵。这是加在常态电流上的惩罚增量，0 为不额外惩罚。超时未完成行礼时，目标＝常态电流＋此增量；例如常态 10、增量 5，目标为 15，仍不超过总上限。\n\n选择惩罚通道、波形和 1–30 秒持续时间。每次超时只触发一次，红色边框提示失败；惩罚结束恢复常态，本轮到点仍优先停止。",
        "penalty_delta_strength" to "填写额外增加的数值，而非惩罚总强度。目标为常态电流＋此值，超过总上限时按上限截取；0 不产生额外惩罚输出。",
        "section_04" to training,
        "training" to training,
        "training_strength" to "忍耐训练的基础目标强度，替代普通常态。动作升幅沿用（各普通动作最高－普通常态）×对应比例，多项取最大值，然后加训练基础并限制到全局最高；实际可能达到的最高值可在第 02 组预览中查看。\n\n基础与动作一起按每秒 30 缓升。设备模式启用时，基础需为 1 到全局最高。",
        "training_rate" to "固定为每秒 30 协议强度单位，基础强度与动作增量一起缓升。普通动作增量上升速度设置不会改变这里的规则；总上限仍生效，下降立即生效。",
        "train_gap_min" to "随机忍耐训练间隔的下界，范围 5–300 秒，不得大于最长间隔。训练与屈膝礼不重叠，训练结束后再安排行礼任务。",
        "train_gap_max" to "随机忍耐训练间隔的上界，范围 5–300 秒，不得小于最短间隔。所有训练仍包含在本轮总时长里。",
        "train_duration_min" to "随机训练持续时间的下界，范围 1–30 秒，不得大于最长持续时间。临近本轮结束不再开启训练。",
        "train_duration_max" to "随机训练持续时间的上界，范围 1–30 秒，不得小于最短持续时间。训练期间仍监测动作违规，目标由训练基础与动作增量相加得到。",
        "section_05" to "小公主，先选好养成模式再开始罚站喵。默认虚拟调试，只在本机模拟；设备输出每次打开应用默认关闭。即使已经扫码配对，选择虚拟模式也不会向设备发送输出喵。两种模式互斥；若同时关闭，则只演练识别与任务，不产生模拟或设备输出。\n\n所有强度默认 0，先设置总上限和各项数值。模式、参数和波形在下一轮开始时应用，游玩中不能修改。",
        "virtual" to "想先练习站姿和行礼，就选虚拟调试喵。无需连接电击器，采用与设备模式相同的识别、计时、波形和输出规则，只在本机模拟，不向设备发送输出。强度默认 0 时，模拟输出也为 0。\n\n" + logs,
        "settings_code" to "小公主的规矩可以用一段设置代码保存啦喵。导出按钮会把当前填写的完整参数复制到剪贴板；复制已保存的代码后，点击导入按钮即可应用。剪贴板没有设置代码时，会打开粘贴输入框。\n\n包含第 02–05 组所有参数、玩法和模式选择、各预设的通道/波形/强度/时长，以及独立隐藏骨架、实验遮脸开关与大小/宽高/位置调整、外部服务器地址和控制台显示偏好。校验全部通过才应用，损坏、不兼容、缺项或越界代码不会覆盖当前设置。导入导出仅在停止状态可用。\n\n导入仅恢复设置，不开始校准、计时或设备输出。代码可恢复设备模式的勾选，需另行配对、点击开始并完成校准才会输出；每次重新打开应用仍默认虚拟模式、设备输出关闭。外部地址需下次手动连接时应用。\n\n设置代码不包含二维码配对、当前连接、人物坐标、日志和本轮进度；手机局域网地址与摄像头选择仍按本机操作。代码以 CVSET1. 开头，请完整复制保留末尾校验内容。",
        "output" to "启用后仍需完成 DGLAB 4 配对、设置有效总上限和强度、完成校准，才会向已连接设备提交输出。与虚拟调试互斥，每次打开应用默认关闭；这些数值是协议强度单位，不是安培读数。\n\n停止、总时间到点和退出前台会结束本轮；网络断开时无法保证停止指令送达设备。",
        "section_06" to logs + "\n\n人物丢失时暂停输出及计时，按画面指引恢复；退出前台或连接异常会结束本轮。",
        "logs" to logs,
        "face_mosaic" to "实验功能喵：开启后，在实时视频中用纯白椭圆遮住眼、鼻、口区域，默认更扁一些，不必遮住整个头部。定位仍复用现有动捕，不增加独立人脸模型。遮挡直接叠在视频预览上，与骨架显示分开；首页、游戏及镜子模式都保留。\n\n整体大小 20–400%，宽度和高度各 20–300%，左右和上下各可移动画面尺寸的 −50% 到 50%。先把位置对准眼鼻口，再分别调宽高；圆度由宽高比例决定。范围放宽后可以调得很小，请自己确认没有露出要遮挡的区域喵。\n\n新装默认关闭，升级沿用旧遮脸开关与旧大小/位置数值；新增宽度默认 100%、高度 75%。重置恢复整体 80%、宽 100%、高 75%、位置 0。停止状态可调整，不重启摄像头；未点击开启镜头时不访问摄像头。\n\n只是实验显示覆盖，不改变动作判定、计时或强度；不转图、不拷贝整帧、不做像素马赛克。短暂丢点保留旧位置最多 0.6 秒，关闭/后台/换镜头/尺寸变化清理旧位置。首次定位前、快速移动或遮挡时可能漏遮，不遮旁人的脸，不保证逐帧完整隐私。实际覆盖和帧率需要手机确认。不录制、不保存或上传画面，原回退检查点保留。",
        "face_cover_size" to "整体大小相对自动估计区域的倍率，范围 20–400%，新装和重置默认 80%。宽度与高度还会分别乘以各自比例。旧版保存的大小数值继续沿用，不会自动覆盖喵。",
        "face_cover_width" to "椭圆横向宽度比例，20–300%，默认 100%。只拉宽或收窄遮挡，不移动中心，也不改变高度。配合整体大小，覆盖眼睛两侧到鼻口即可喵。",
        "face_cover_height" to "椭圆纵向高度比例，20–300%，默认 75%，使默认遮挡较扁。只拉高或压扁，不移动中心，不改变宽度；高度与宽度相同可恢复圆形。",
        "face_cover_x" to "左右偏移范围为视频画面宽度的 −50% 到 50%，默认 0。正值向屏幕右侧，负值向左，前置镜像后仍按屏幕方向。偏移不能修复方向反转；请先确认遮挡与人同向移动。",
        "face_cover_y" to "上下偏移范围为视频画面高度的 −50% 到 50%，默认 0。正值向下，负值向上。中心默认靠近眼鼻口，可据手机效果调整；重置会同时恢复整体大小、宽度、高度和位置。",
        "hide_skeleton" to "独立隐藏骨架、关节点和动作参考线，首页预览、校准及游戏中均生效，不要求开启镜子模式，也不要求开启遮脸喵。动捕、动作判断、计时和输出继续运行。不会隐藏或关闭白色遮脸，也不会隐藏控制台和停止按钮。\n\n选择会保存并随设置代码导入导出；进入游戏和关闭遮脸不会重置。镜子模式另行隐藏界面，退出镜子后仍按本选项决定骨架是否可见。游玩期间按原规则锁定设置，需停止后修改。",
        "mirror_mode" to "开启后，完成全部校准才自动进入镜子模式喵：隐藏骨架、文字、控制台和按钮，只保留摄像头画面、已开启的遮脸及无文字边框提示。开始时短亮绿框确认启动；原有黄/蓝/绿/红阶段提示照常显示。镜子模式只改变显示，不改变识别、计时、强度或镜头方向。\n\n轻点画面可退出镜子模式并显示停止按钮，手机返回键直接停止并返回设置。人物丢失或局部测量不足、暂停输出时自动退出；主体丢失重新完成校准后可自动进入，局部测量恢复不会立即隐藏控制界面。此开关保存在“05 养成模式”，本轮游玩期间锁定。",
        "console" to "实时显示阶段、手脚分值、目标/本机计算/虚拟或提交强度、上限和波形。设备模式保留官方 App 强度与 RPC 清理状态，异常单独记录；本机提交与 App 回报都不代表人体电流测量。隐藏控制台不停止识别或边框提醒。查看说明不暂停本轮。\n\n" + logs,
        "pairing" to pairing,
        "pairing_v3" to "使用外部 V3 服务的兼容配对码，仅供旧连接流程测试，不支持本版游戏设备输出。需要真实联动时，请关闭外部连接，使用内置两手机连接并由另一部手机的 DGLAB 4 扫码。二维码仅对当前连接有效。",
        "waveform" to "选择这个预设播放的波形，点击选项即可选中，取消则保留原选择。设置在下一轮开始时应用；通道、强度和时长仍以对应预设设置为准。三连提示固定三秒，不同提示形式不改变判定开始的时刻。"
    )

    fun text(key: String): String? = entries[key]
}
